def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    desperate_pressure = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 300:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_pressure += 1
            if prev.get('status') == 'lost' and opp.get('hp', 10) <= 4:
                desperate_pressure += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 1:
        urgency += 3
    if supply_tight:
        urgency += 2
    elif supply_loose:
        urgency -= 1
    urgency += min(2, desperate_pressure)

    if urgency >= 6:
        target = max(0.95 * DAILY_SALARY, highest_prev + 3.0)
    elif urgency >= 4:
        target = max(0.78 * DAILY_SALARY, avg_prev + 2.0, highest_prev * 0.72)
    elif urgency >= 2:
        target = max(0.55 * DAILY_SALARY, avg_prev * 0.82 + 1.0)
    else:
        target = max(0.28 * DAILY_SALARY, avg_prev * 0.55)

    if rich_count >= 2 and urgency <= 2:
        target *= 0.9
    if supply_loose and urgency <= 3:
        target *= 0.88
    if day >= 8 and hp <= 4:
        target = max(target, 0.85 * DAILY_SALARY)

    reserve_floor = 0.0
    if hp > 3 and day <= 7:
        reserve_floor = DAILY_SALARY * 1.2
    max_affordable = max(0.0, budget - reserve_floor)
    if urgency >= 4:
        max_affordable = budget

    bid = min(target, max_affordable if max_affordable > 0 else budget)
    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, highest_prev + 4.0, 0.92 * DAILY_SALARY))

    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from traces for immediate reaction
    yesterday_bids = []
    highest_prev_bid = None
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = float(prev['bid'])
            yesterday_bids.append(b)
            if highest_prev_bid is None or b > highest_prev_bid:
                highest_prev_bid = b

    # Supply pressure: higher supply reduces need to overbid
    # Expected number of water units roughly scales with supply/WATER_REQ
    # (use only to adjust aggressiveness)
    supply_ratio = supply / float(WATER_REQ)

    # Emergency if low HP or already several no-water days
    emergency = (hp <= 2.5) or (no_water_days >= 2)

    # Determine base bid using yesterday's strongest pressure
    # If someone was bidding very high yesterday, raise our bid to not get starved.
    if highest_prev_bid is not None:
        high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85
        if emergency:
            target = DAILY_SALARY * (0.88 if high_pressure else 0.78)
        else:
            if high_pressure:
                # Match the pressure but not fully; aim to win with moderate edge
                target = max(highest_prev_bid * 0.92, DAILY_SALARY * 0.45)
            else:
                target = max(highest_prev_bid * 0.75, DAILY_SALARY * (0.48 + 0.08 * (supply_ratio - 1.0)))
    else:
        if emergency:
            target = DAILY_SALARY * 0.85
        else:
            target = DAILY_SALARY * (0.55 + 0.08 * (supply_ratio - 1.0))

    # If supply is low (closer to 15), slightly increase bid; if high (closer to 25), decrease
    if supply <= float(MIN_SUPPLY):
        target *= 1.08
    elif supply >= float(MAX_SUPPLY):
        target *= 0.95

    # Clamp to budget and keep within reasonable bounds
    target = max(0.0, target)
    bid = min(budget, target)

    # If we have extremely low budget, bid what we can
    if bid < 1e-6:
        bid = min(budget, DAILY_SALARY * 0.1)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Gather yesterday's bids from previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        # If previous max is high, we need to outbid slightly
        if max_prev >= DAILY_SALARY * 0.8:
            target = avg_prev + 2.0
        else:
            target = avg_prev + 1.0
    else:
        target = DAILY_SALARY * 0.5

    # Adjust based on HP, day, and supply
    if hp <= 2:
        target = max(target, DAILY_SALARY * 0.9)
    elif day >= 8:
        target = max(target, DAILY_SALARY * 0.7)
    else:
        target = max(target, DAILY_SALARY * 0.4)

    # Ensure we don't exceed budget and bid at least 0
    bid = min(budget, target)
    return max(0.0, bid)
